import{_ as o,l as s,o as a,c,v as t,p as d,x as r,d as n,i as l,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"缓冲与脏页","description":"","frontmatter":{"title":"缓冲与脏页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/buffer-dirty.md","filePath":"cs/buffer-dirty.md","lastUpdated":1789023840000}'),p={name:"cs/buffer-dirty.md"};function m(f,e,u,_,E,C){const i=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="缓冲与脏页" tabindex="-1">缓冲与脏页 <a class="header-anchor" href="#缓冲与脏页" aria-label="Permalink to &quot;缓冲与脏页&quot;">​</a></h1><div class="epigraph"><p>磁盘块在内存里有一份缓存；写先标脏，稍后才回写。崩溃时内存与介质可以不一致。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；McKusick 等对 Unix 缓冲缓存的整理</footer></div><p><a href="/cs/mount-super">上一课</a>让读写落到块号。<a href="/cs/mmap">mmap</a> 与 <a href="/cs/demand-paging">按需调页</a>已经把文件页放进帧。缺口是统一承认：<strong>页 Cache / 缓冲缓存</strong>是磁盘的 Cache，脏位表示比介质新。数据库栏的 <a href="/cs/wal">WAL</a> 正是在这个前提下谈日志先行。本课只钉缓冲与脏，不选磁盘臂算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次 <code>write</code> 若都同步落盘，管道式小写会把吞吐打穿。若只改内存，断电丢数据。缺口不是新的 inode 字段，而是策略：写进帧并标脏；读命中则不访盘；回写可由定时器、内存压力（<a href="/cs/page-replace">置换</a>）或 <code>fsync</code> 触发。同一物理块不应在缓冲里有两份互相不知道的副本。</p><p>本课不把 write-back 与 write-through 的微架构 Cache 课再推一遍；对象换成磁盘块。</p><p><span class="marginnote">脏页是还没到稳定介质的字节。<code>fsync</code> 要求该文件相关脏页与必要元数据到达持久存储。组提交与延迟分配是优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查页 Cache，无则分配帧、读盘、插入。写：在 Cache 中修改，标脏。置换选到脏页必须先写盘。元数据（inode、目录）同样走缓冲，崩溃可留下「目录项在、inode 未分」或相反，这是 fsck 与日志要补的，本课只暴露不一致可能。</p>',9)),(a(),d(h,null,{default:r(()=>[l(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RW%5B%22read%2Fwrite%2Fmmap%22%5D%20--%3E%20CACHE%5B%22%E9%A1%B5%20Cache%22%5D%0A%20%20CACHE%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%3A%20%E4%B8%8D%E8%AE%BF%E7%9B%98%22%5D%0A%20%20CACHE%20--%3E%20DIRTY%5B%22%E5%86%99%E5%88%99%E8%84%8F%22%5D%0A%20%20DIRTY%20--%3E%20WB%5B%22%E5%9B%9E%E5%86%99%20%2F%20fsync%20%2F%20%E7%BD%AE%E6%8D%A2%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓冲把磁盘的高延迟从大多数 <code>read</code> 里拿掉，让<a href="/cs/scheduling-metrics">调度指标</a>里的 I/O 等待下降。它也让 mmap 与 <code>read</code> 看见同一帧成为可能：统一 Cache。脏页是正确性与性能的交界：OS 允许短暂不一致；数据库用 WAL 在更高层再加一条顺序。本栏不把关系库的 REDO 写进文件系统课。</p><p>与关中断锁的关系：Cache 索引是共享结构，下半部完成 DMA 后要把页标有效，锁规则沿用同步课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 O_DIRECT 绕过 Cache 的全部语义，不把电池后备写缓存当默认硬件。也不保证 <code>write</code> 返回即持久——那正是脏页的含义。下一课才问：许多脏页要写时，请求以什么顺序送向设备。</p><p>写回顺序若先数据后 inode 大小，崩溃可能泄露旧数据；日志文件系统用事务把元数据捆在一起，本课只承认问题存在。</p><p>后课默认：内存可以比磁盘新。回写与读请求如何排队到磁头或闪存，下一课磁盘调度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文件页经统一 Cache；写标脏，稍后回写。</li><li>崩溃时允许不一致；fsync 是显式持久。</li><li>WAL 假定本课这个缺口已经在。</li><li>出处：Silberschatz et al., <em>OSC</em>；McKusick, Bostic, Karels, Quarterman, <em>The Design and Implementation of the 4.4BSD Operating System</em>。</li></ul>',9))])}const b=o(p,[["render",m]]);export{D as __pageData,b as default};
